/**
 * Demo data is generated by replaying real domain operations day by day, so
 * every timeline, follow-up count and status is exactly what the automation
 * engine would have produced. Quotes are flagged `isDemo` so they can be
 * cleared in Settings.
 */

interface DemoScript {
  customer: { name: string; email: string; phone: string | null };
  serviceIndex: number;
  amount: number;
  sentDaysAgo: number;
  /** What happened on which day (relative to sent date). Omit for still-active quotes. */
  outcome?: { type: "replied" | "won" | "lost" | "paused"; onDay: number; thenWonOnDay?: number };
  schedule?: number[];
  notes?: string;
}

