const EMPTY: WorkspaceData = { customers: [], quotes: [], followUps: [], timeline: [], inbound: [] };

function quoteNumber(index: number, today: ISODate): string {
  const year = today.slice(0, 4);
  return `EST-${year}-${String(1040 + index).padStart(4, "0")}`;
}

export function buildDemoWorkspace(account: Account, today: ISODate): WorkspaceData {
  const services = DEMO_SERVICES[account.business.type] ?? DEMO_SERVICES.other;
  let data = EMPTY;

  SCRIPTS.forEach((script, index) => {
    const sentAt = addDays(today, -script.sentDaysAgo);
    const schedule = script.schedule ?? account.settings.defaultSchedule;
    const startCtx = createContext(account.business, account.settings, sentAt);

    const added = addQuote(
      data,
      {
        customerName: script.customer.name,
        customerEmail: script.customer.email,
        customerPhone: script.customer.phone ?? "",
        quoteNumber: quoteNumber(index, today),
        serviceDescription: services[script.serviceIndex % services.length],
        amount: script.amount,
        sentAt,
        notes: script.notes ?? "",
        schedule,
        tone: account.settings.defaultTone,
      },
      startCtx,
      { isDemo: true },
    );
    data = added.data;
    const quoteId = added.quote.id;

    // Replay each day since the quote was sent.
    for (let day = 0; day <= script.sentDaysAgo; day += 1) {
      const date = addDays(sentAt, day);
      const ctx = createContext(account.business, account.settings, date);

      if (script.outcome && script.outcome.onDay === day) {
        if (script.outcome.type === "replied") data = markReplied(data, quoteId, ctx);
        if (script.outcome.type === "won") data = markWon(data, quoteId, ctx);
        if (script.outcome.type === "lost") data = markLost(data, quoteId, ctx);
        if (script.outcome.type === "paused") data = pauseQuote(data, quoteId, ctx);
      }
      if (script.outcome?.thenWonOnDay === day) {
        data = markWon(data, quoteId, ctx);
      }

      data = runAutomation(data, ctx).data;
    }
  });

  return data;
}

