/** Fictional other accounts so the owner admin view has something to show. */
export function buildDemoPlatformAccounts(today: ISODate): PlatformAccount[] {
  return DEMO_ACCOUNTS.map((spec) => {
    const createdAt = instantOn(addDays(today, -spec.daysAgo));
    const user: User = {
      id: createId("user"),
      name: spec.owner,
      email: `${spec.owner.toLowerCase().replace(/\s+/g, ".")}@example.com`,
      createdAt,
    };
    const business: Business = {
      id: createId("biz"),
      ownerUserId: user.id,
      name: spec.business,
      ownerName: spec.owner,
      email: user.email,
      type: spec.type,
      createdAt,
    };
    const subscription: Subscription = {
      id: createId("sub"),
      businessId: business.id,
      plan: spec.plan,
      status: spec.status,
      stripeCustomerId: null,
      stripeSubscriptionId: null,
      trialEndsAt: spec.status === "trialing" ? instantOn(addDays(today, 14 - spec.daysAgo)) : null,
      createdAt,
    };
    return { user, business, subscription };
  });
}
